import{_ as n,C as i,c as l,o as h,a3 as r,G as o,j as a,a as s}from"./chunks/framework.Dokpd4od.js";const b=JSON.parse('{"title":"Terminal tour","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/selling/terminal-overview.md","filePath":"master/sales/point-of-sale/selling/terminal-overview.md","lastUpdated":1792041590000}'),d={name:"master/sales/point-of-sale/selling/terminal-overview.md"};function g(p,e,u,c,m,T){const t=i("ImagePopup");return h(),l("div",null,[e[0]||(e[0]=r('<h1 id="terminal-tour" tabindex="-1">Terminal tour <a class="header-anchor" href="#terminal-tour" aria-label="Permalink to &quot;Terminal tour&quot;">​</a></h1><p>The terminal is where you sell. It has a product area on the left and the current order on the right. This page names every part of the screen, so you know where to click before your first sale.</p><blockquote><p><strong>In simple words:</strong> Products on the left, the order on the right, buttons and the number pad underneath.</p></blockquote><h2 id="open-the-terminal" tabindex="-1">Open the terminal <a class="header-anchor" href="#open-the-terminal" aria-label="Permalink to &quot;Open the terminal&quot;">​</a></h2><p>Open <code>/pos/registers</code> in your browser, or click <strong>Open Register</strong> or <strong>Continue Selling</strong> on the back office <strong>Dashboard</strong>. Pick your register. The terminal opens on the <strong>Home</strong> page.</p>',5)),o(t,{src:"/images1/pos/terminal_registers.png",alt:"Terminal Registers page listing the two registers with Resume and Open register buttons"}),e[1]||(e[1]=r('<h2 id="the-top-bar" tabindex="-1">The top bar <a class="header-anchor" href="#the-top-bar" aria-label="Permalink to &quot;The top bar&quot;">​</a></h2><ul><li><strong>Registers:</strong> Goes back to the list of registers.</li><li><strong>Home:</strong> The selling screen. In a restaurant this is the floor plan first.</li><li><strong>Your initials:</strong> Opens the menu with <strong>Orders</strong> (past and open orders, see <a href="./refunds.html">Refunds</a>), <strong>Cash In / Out</strong>, <strong>Install app</strong>, <strong>Toggle theme</strong>, <strong>Back office</strong>, <strong>Close register</strong> and <strong>Log out</strong>.</li></ul>',2)),o(t,{src:"/images1/pos/terminal_user_menu.png",alt:"Terminal user menu open with Orders, Cash In / Out, Install app, Toggle theme, Back office, Close register and Log out"}),e[2]||(e[2]=r('<h2 id="the-product-area" tabindex="-1">The product area <a class="header-anchor" href="#the-product-area" aria-label="Permalink to &quot;The product area&quot;">​</a></h2><ol><li>Use <strong>Search products</strong> to find a product by name.</li><li>Click a <strong>category tile</strong>, such as <strong>Audio</strong> or <strong>Accessories</strong>, to show only that category.</li><li>Click a product tile to add one unit to the order. Click it again to add more.</li></ol>',2)),o(t,{src:"/images1/pos/terminal_home_retail.png",alt:"TechNest retail terminal with search box, category tiles, product grid and the order panel"}),e[3]||(e[3]=r('<p>Each tile shows the name, the price and, if it is already on the order, the quantity in the corner. The red <strong>i</strong> icon opens the product information with stock, price, cost and margin.</p><p>The blue <strong>+</strong> button next to the search box creates a new product on the spot.</p><h2 id="the-order-tabs" tabindex="-1">The order tabs <a class="header-anchor" href="#the-order-tabs" aria-label="Permalink to &quot;The order tabs&quot;">​</a></h2><p>At the top right of the product area you see the order tabs.</p><ul><li>The chip with a number, such as <strong>401</strong>, is the <strong>tracking number</strong> of the order. It is also printed on the receipt.</li><li>The hamburger icon lists all open orders.</li><li>The <strong>+</strong> icon starts a new order. Orders you set aside stay open until you come back.</li></ul><h2 id="the-order-panel" tabindex="-1">The order panel <a class="header-anchor" href="#the-order-panel" aria-label="Permalink to &quot;The order panel&quot;">​</a></h2><p>The right side shows the current order.</p><ul><li><strong>Lines:</strong> Product, quantity x price and the line total. Click <strong>X</strong> to remove a line.</li><li><strong>Subtotal, Taxes, Total:</strong> The running amounts.</li><li><strong>Customer:</strong> Picks the customer. See <a href="./order-notes-and-customers.html">Notes and customers</a>.</li><li><strong>Note:</strong> Adds a note to the selected line.</li><li><strong>Actions:</strong> More options for the order, such as <strong>Cancel order</strong>. In a restaurant it also holds <strong>Guests</strong> and <strong>Transfer / Merge</strong>.</li><li><strong>Payment:</strong> Goes to the payment screen. See <a href="./pay-and-receipt.html">Pay and receipt</a>.</li></ul><h2 id="the-number-pad" tabindex="-1">The number pad <a class="header-anchor" href="#the-number-pad" aria-label="Permalink to &quot;The number pad&quot;">​</a></h2><p>The pad changes the selected line. Click a line first, then choose a mode.</p><ul><li><strong>Qty:</strong> Types the quantity. Enter 3 to make the quantity 3.</li><li><strong>%:</strong> Types a discount percentage for the line. The mode is active only when line discounts are on.</li><li><strong>Price:</strong> Types a new unit price for the line. It works only when price changes are allowed.</li><li><strong>+/-:</strong> Switches the sign of the number.</li><li><strong>Backspace:</strong> Deletes the last digit.</li></ul>',11)),o(t,{src:"/images1/pos/terminal_numpad.png",alt:"Number pad with the Qty, percent and Price modes, +/- key, backspace key and Payment button"}),e[4]||(e[4]=a("h2",{id:"the-orders-page",tabindex:"-1"},[s("The Orders page "),a("a",{class:"header-anchor",href:"#the-orders-page","aria-label":'Permalink to "The Orders page"'},"​")],-1)),e[5]||(e[5]=a("p",null,[s("Click "),a("strong",null,"Orders"),s(" in the menu to see orders of this register. You can filter by status, search and select an order. Use it for refunds and invoices.")],-1)),o(t,{src:"/images1/pos/terminal_orders_page.png",alt:"Terminal Orders page with the order list, the All active orders filter and the details panel"}),e[6]||(e[6]=r('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A barcode scanner works anywhere on the till. Scan a product and it goes to the order.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./take-an-order.html">Take an order</a></li><li><a href="./restaurant-tables.html">Restaurant tables</a></li><li><a href="./../sessions/open-register.html">Open the register</a></li></ul>',3))])}const f=n(d,[["render",g]]);export{b as __pageData,f as default};
